{
  "title":"Bộ câu hỏi vật lý nhiệt động lực học nâng cao",
  "category":"categories.science",
  "plans":[
    {
      "id":"P28",
      "type":"true_false",
      "recordIds":["F5"],
      "intent":"Xác định áp suất mới của khí trong lốp khi nhiệt độ tăng từ 27 °C lên 54 °C, giữ thể tích không đổi, và khẳng định rằng áp suất tăng lên 5,45 atm.",
      "reasoningSteps":[
        "Chuyển đổi nhiệt độ sang Kelvin: T1=27+273=300 K, T2=54+273=327 K.",
        "Áp dụng định luật khí lý tưởng ở thể tích không đổi: P1/T1 = P2/T2 → P2 = P1·T2/T1 = 5 atm·327/300 ≈ 5,45 atm."
      ]
    },
    {
      "id":"P29",
      "type":"short_answer",
      "recordIds":["F12"],
      "intent":"Tính công thực hiện bởi khí khi piston di chuyển lên 5 cm trong xilanh có đường kính 20 cm và áp suất không đổi 102 kPa.",
      "reasoningSteps":[
        "Tính diện tích mặt cắt của xilanh: A = π·(d/2)^2 = π·(0.20 m/2)^2 = π·0.01 m² ≈ 0,0314 m².",
        "Tính thay đổi thể tích: ΔV = A·Δh = 0,0314 m²·0,05 m ≈ 1,57×10⁻³ m³.",
        "Công thực hiện: W = P·ΔV = 102 000 Pa·1,57×10⁻³ m³ ≈ 1,60×10² J."
      ]
    },
    {
      "id":"P30",
      "type":"multiple_choice",
      "recordIds":["F14"],
      "intent":"Xác định áp suất tuyệt đối trong xi lanh khi một học sinh 24 kg ngồi lên ghế, biết tổng khối lượng ghế + xi lanh là 6 kg, diện tích piston 30 cm², độ hạ 12 cm và áp suất khí quyển 1,0×10⁵ Pa; lựa chọn đáp án đúng trong bốn lựa chọn.",
      "reasoningSteps":[
        "Tính tổng lực trọng lượng: F = (24 kg + 6 kg)·g = 30 kg·10 m/s² = 300 N.",
        "Chuyển đổi diện tích piston sang mét vuông: S = 30 cm² = 30×10⁻⁴ m² = 0,003 m².",
        "Tính tăng áp suất do trọng lượng: Δp = F/S = 300 N / 0,003 m² = 1,0×10⁵ Pa.",
        "Áp suất tuyệt đối trong xi lanh: p = p₀ + Δp = 1,0×10⁵ Pa + 1,0×10⁵ Pa = 2,0×10⁵ Pa."
      ]
    }
  ]
}
